import{_ as t,o,c as a,a2 as i}from"./chunks/framework.1L7G9bmn.js";const g=JSON.parse('{"title":"Feature Development Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"standards/02_FEATURE_DEVELOPMENT_WORKFLOW.md","filePath":"standards/02_FEATURE_DEVELOPMENT_WORKFLOW.md"}'),n={name:"standards/02_FEATURE_DEVELOPMENT_WORKFLOW.md"};function r(s,e,l,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="feature-development-workflow" tabindex="-1">Feature Development Workflow <a class="header-anchor" href="#feature-development-workflow" aria-label="Permalink to &quot;Feature Development Workflow&quot;">​</a></h1><p>This document outlines the standard operating procedure for adding new features to the project. AI agents must follow this pipeline sequentially.</p><h2 id="_1-requirement-planning-phase" tabindex="-1">1. Requirement &amp; Planning Phase <a class="header-anchor" href="#_1-requirement-planning-phase" aria-label="Permalink to &quot;1. Requirement &amp; Planning Phase&quot;">​</a></h2><ul><li><strong>Understand the Goal:</strong> Cross-reference requests against the strategic roadmap (<code>research/Expected_features_speed_Assist_Product_Roadmap.md</code>). If a feature violates the core pivot (e.g., adding a heavy map module), flag it.</li><li><strong>Create an Implementation Plan:</strong> For any non-trivial change, AI must output an <code>implementation_plan.md</code> detailing: <ul><li>Which layers (<code>data</code>, <code>domain</code>, <code>presentation</code>) will change.</li><li>What new classes or tests will be created.</li></ul></li><li><strong>Wait for Approval:</strong> Do not write code until the user approves the plan.</li></ul><h2 id="_2-execution-phase-ai-developer-workflow" tabindex="-1">2. Execution Phase (AI &amp; Developer Workflow) <a class="header-anchor" href="#_2-execution-phase-ai-developer-workflow" aria-label="Permalink to &quot;2. Execution Phase (AI &amp; Developer Workflow)&quot;">​</a></h2><p>When executing a new feature, strict adherence to the following sequence is mandatory. <strong>Do not make any assumptions, fail out loud, and ask for clarity.</strong></p><ol><li><strong>Information Gathering:</strong> Clarify requirements and gather any necessary mockups or existing references.</li><li><strong>Analysis:</strong> Analyze the codebase to find where the feature fits cleanly without breaking existing logic.</li><li><strong>Preview (Diff Style):</strong> Propose the exact code changes to the user using a <code>diff</code> style format. Clearly state the class names and functions being modified or created.</li><li><strong>Approval &amp; Execution:</strong> <strong>Stop and wait.</strong> Do not apply corrections or write the code until explicit approval is given by the user. Once approved, apply the exact changes.</li><li><strong>Post-Correction Review:</strong> After applying the feature, show the resulting code changes using a <code>diff</code> style summary to confirm the exact modifications made.</li><li><strong>Module Separation (SDK Architecture):</strong> Write logic in the appropriate module (<code>:speed-core</code>, <code>:speed-ui</code>, <code>:speed-overlay</code>, <code>:speed-autostart</code>, <code>:speed-bom</code>). Keep <code>:speed-core</code> headless with zero Compose dependencies.</li></ol><h2 id="_3-testing-phase-mandatory" tabindex="-1">3. Testing Phase (Mandatory) <a class="header-anchor" href="#_3-testing-phase-mandatory" aria-label="Permalink to &quot;3. Testing Phase (Mandatory)&quot;">​</a></h2><p>Every new feature or bug fix MUST be accompanied by unit and/or UI tests.</p><ul><li><strong>Unit Tests:</strong> Use <strong>JUnit4 / Robolectric</strong>, <strong>MockK</strong>, and <strong>kotlinx-coroutines-test</strong>. <ul><li>Domain telematics algorithms (<code>TelematicsEngine</code>, <code>SpeedWatcher</code>, <code>SpeedUnit</code>) and repository implementations must have high branch and line coverage (target &gt; 90%).</li><li><strong>Verification:</strong> Run <code>./gradlew testDebugUnitTest</code> locally to ensure all test suites pass before committing.</li></ul></li><li><strong>UI Tests:</strong> Use <strong>Compose Testing rules</strong> (<code>createComposeRule</code>) to verify that UI elements render correctly based on specific <code>SpeedData</code> and <code>UiState</code> inputs.</li><li><strong>CI/CD Quality Gates:</strong> All commits and Pull Requests are automatically validated by GitHub Actions (<code>.github/workflows/quality-gates.yml</code>).</li></ul><h2 id="_4-verification-documentation" tabindex="-1">4. Verification &amp; Documentation <a class="header-anchor" href="#_4-verification-documentation" aria-label="Permalink to &quot;4. Verification &amp; Documentation&quot;">​</a></h2><ul><li><strong>Run Quality Gates:</strong> Before concluding any task or pushing code, run the strict static analysis gates: <ul><li>Run <code>./gradlew detekt lintDebug</code></li><li>Fix any code smells or formatting issues reported by these tools.</li></ul></li><li><strong>Run the Build:</strong> Always verify that the project compiles via <code>./gradlew assembleDebug</code>.</li><li><strong>Update Docs:</strong> If you added or modified public APIs, update the web documentation in <code>docs/</code> and verify the build with <code>npm run docs:build --prefix docs</code>.</li><li><strong>Walkthrough:</strong> Generate a <code>walkthrough.md</code> summarizing what was built, how it was tested, and how to verify the feature.</li></ul>',12)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
